"""blockcopy_pp (pixel->pixel) candidate emitter.

Generic SVE row copy for 8-bit blocks; used as representative slices for
the nested cu/pu/chroma fields (docs/37).
"""


def emit(func_name, width, height):
    lines = [
        "// Generated by tools/emit_blockcopy_pp_sve2_shared.py -- do not edit.",
        "#include <arm_sve.h>",
        "#include <stdint.h>",
        "#include <stddef.h>",
        "",
        "extern \"C\" void %s(uint8_t* dst, intptr_t dstStride,"
        " const uint8_t* src, intptr_t srcStride)" % func_name,
        "{",
    ]
    for c in range(0, width, 32):
        n = min(32, width - c)
        lines.append(
            "    const svbool_t pg%d = svwhilelt_b8((uint32_t)0,"
            " (uint32_t)%d);" % (c, n))
    lines.append("    for (int r = 0; r < %d; r++)" % height)
    lines.append("    {")
    for c in range(0, width, 32):
        lines.append(
            "        svst1_u8(pg%d, dst + r * dstStride + %d,"
            " svld1_u8(pg%d, src + r * srcStride + %d));"
            % (c, c, c, c))
    lines.append("    }")
    lines.append("}")
    return "\n".join(lines) + "\n"


def emit_combo(combo, func_name, width, height):
    return emit(func_name, width, height)
